import type { AddNumbersInput, AddNumbersOutput, BenchAddInput, BenchAddOutput, BenchBytesPayload, BenchPairPayload, BenchStringPayload, ChannelDemoInput, ChannelDemoOutput, ClampInput, ClampOutput, CreateItemInput, CreateItemOutput, DivideInput, DivideOutput, EmitDemoInput, EmitDemoOutput, GaugeInput, GaugeOutput, GreetInput, GreetOutput, IsEvenInput, IsEvenOutput, MultiplyInput, MultiplyOutput, ProcessItemInput, ProcessItemOutput, RegistryDemoInput, RegistryDemoOutput, ResourceCloseInput, ResourceCloseOutput, ResourceHandleOutput, ResourceOpenInput, ResourceReadInput, ResourceReadOutput, ResourceWriteInput, ResourceWriteOutput, ScoreTotalInput, ScoreTotalOutput, SecureComputeInput, SecureComputeOutput, SizeOfInput, SizeOfOutput, SpanInput, SpanOutput, SumListInput, SumListOutput, ToUpperInput, ToUpperOutput } from './types.js';
import type { InvokeOptions } from '@rustra/types';

/** JSI 네이티브 모듈의 최소 인터페이스 — invokeTypedPos 노출 호스트 권장. */
export type PositionalNative = {
  invokeTyped(name: string, args: unknown): unknown;
  /** (P0-3) cmd_id 진입 — 문자열 마샬링을 건너뛴다. 미노출이면 이름 기반으로 폴백. */
  invokeTypedById?(cmdId: number, args: unknown): unknown;
  /** (Tier 1) positional 진입 — JS 인자 객체 생성/프로퍼티 조회를 통째로 건너뛴다. */
  invokeTypedPos?(cmdId: number, ...fields: unknown[]): unknown;
};

let _native: PositionalNative | null = null;

/** 앱 시작 시 JSI 네이티브를 주입한다 (installRustraJSI 이후). */
export function installRustraPositional(native: PositionalNative): void {
  _native = native;
}

function requireNative(): PositionalNative {
  if (!_native) {
    throw new Error('positional facade not installed — call installRustraPositional(native) first');
  }
  return _native;
}

/** byId 진입(우선) — 미노출 구 네이티브는 이름 기반 invokeTyped 로 폴백. */
function call<T>(cmdId: number, name: string, args: unknown): T {
  const native = requireNative();
  if (native.invokeTypedById) {
    return native.invokeTypedById(cmdId, args) as T;
  }
  return native.invokeTyped(name, args) as T;
}

/** (Tier 1) positional 진입 — 개별 인자를 그대로 넘긴다(객체 생성 0). */
function callPos<T>(cmdId: number, ...fields: unknown[]): T {
  const native = requireNative();
  if (native.invokeTypedPos) {
    return native.invokeTypedPos(cmdId, ...fields) as T;
  }
  // 구 네이티브 폴백: 필드 순서는 스키마 프로퍼티 순(생성 시점 필드 리스트)과 동일.
  throw new Error(
    'positional entry unavailable — update the native module (invokeTypedPos)',
  );
}

export function addNumbers(a: number, b: number, options?: InvokeOptions): Promise<AddNumbersOutput> {
  void options;
  return Promise.resolve(callPos<AddNumbersOutput>(1, a, b));
}

